"""This file contains Classes with low level functionality for headless iCOM Vx connections,
reading connection statuses, iCOM Vx messages and tags"""

from ctypes import byref, c_ushort, windll, c_long, c_char_p, create_string_buffer
from ctypes.wintypes import DWORD
from interops.libraries.icom.icom_tag_mappings import defn_to_tag_map, tag_to_def_map
from interops.libraries.icom.icom_error_handling import IcomError, exception_from_err
from interops.libraries.icom.icom_error_codes import *  #TODO - not ideal, find alternative to import all errors codes?
import time
import pprint
import logging

logger = logging.getLogger(__name__)


class IcomVx():

    '''
    Interaction with Vx server.

    Create an instance of this class to begin listening to Vx messages.
    Produces VxMessage instances from raw Vx message iCOM calls.

    Uses Elekta iCOMClient.dll directly from Python.
    iCOMClient.dll is 32-bit and only runs on 32-bit Python.

    Example:
    if __name__ == "__main__":
        lib_path = "C:/Users/gbraidan/Documents/VXDebugTool/iCOMClient.dll"
        vx = IcomVx(lib_path)
        vx.connect(hostip="192.168.150.1")
        loop = 0
        while loop < 5:
            print "\n"
            time.sleep(1)
            msg = vx.get_next_message()
            msg.pretty_print()

            print "MESSAGE SEQ: " + msg.sequence_num()
            print "LINAC STATUS:" + msg.get_machine_state()
            print "MESSAGE DATETIME: "+ msg.date_time()

            print msg.get_run_by_tagname('MachineName')
            print msg.get_set_by_tagname('MachineName')

            #Tag name,Hex Tag,Run,Set,Prescribed
            msg.write_to_file(r"C:\python32bit\_icom_vx_out_1.csv", include_empty_tags=True)
            loop += 1
        vx.disconnect()
    '''

    def __init__(self, lib_path):
        '''
        Constructor.

        Args:
        lib_path (str) - Path to the iCOMClient.dll library.
        '''
        self.icom = windll.LoadLibrary(lib_path)

    def connect(self, hostip, timeout_millis=10000):
        '''
        Create a new connection to the Vx server.

        Args:
        hostip (str) - IP Address of linac host
        timeout_millis (int) -  Timeout to get connection (milliseconds)

        Returns:
        boolean - True if successful

        Raises:
        IcomConnectionError if unsuccessful
        '''
        # In python 3, strings are unicode, but c_char_p() expects a byte object.
        # Convert the unicode string to a byte string before passing to c_char_p().
        ip_ptr = c_char_p(hostip.encode('utf-8'))
        timeout = c_long(timeout_millis)
        result = self.icom.iCOMVXConnect(ip_ptr, timeout)
        if result > 0:
            self.icom_handle = result
            logger.info("CONNECTed VX - " + str(result))
            return True
        else:
            logger.info("FAILED TO CONNECT VX - " + str(result))
            raise exception_from_err("FAILED TO CONNECT VX", result)

    def connection_state_ok(self):
        '''
        Check health and availability of iCOM  Vx connection .

        Returns:
        True if The connection has started and is okay(state=1) else False
        '''
        state = self.icom.iCOMGetConnectionState(self.icom_handle)
        if state == ICOM_RESULT_OK:
            return True
        else:
            return False

    def get_machine_state(self, msg_handle):

        state_decode = {1: 'PREPARATORY',
                        2: 'CONFIRM SETTINGS',
                        3: 'READY TO START',
                        4: 'SEGMENT START',
                        5: 'SEGMENT IRRADIATE',
                        6: 'SEGMENT INTERRUPT',
                        7: 'SEGMENT INTERRUPTED',
                        8: 'SEGMENT RESTART',
                        9: 'SEGMENT TERMINATE',
                        10: 'SEGMENT PAUSE',
                        11: 'FIELD TERMINATE',
                        12: 'TERMINATE CHECKING',
                        13: 'FIELD TERMINATED',
                        14: 'MOVE ONLY'}

        result = self.icom.iCOMGetState(msg_handle)

        if result > 0:
            # logger.info("get_machine_state - " + str(state_decode[result]))
            return state_decode[result]
        else:
            logger.info("get_machine_state Failed- " + str(state_decode[result]))
            raise exception_from_err("Failed to get machine state: ", result)

    def get_linac_function_mode(self, msg_handle):
        '''
        Get the current linac function mode.

        Returns:
        Textual value representing current linac mode.

        Raises:
        IcomConnectionError if connection fails.
        '''
        fxn_decode = {-1: 'Unknown mode',
                      1: 'Premium Therapy Treatment',
                      3: 'Premium Check Radiograph',
                      5: 'Premium Finish Field',
                      8: 'Standard Therapy Treatment',
                      9: 'Receive External Prescription',
                      10: 'Service mode',
                      255: 'Invalid_linac_function_mode_return_value'
                      }
        result = self.icom.iCOMGetFunction(msg_handle)
        if result >= -1:
            return fxn_decode[result]
        else:
            logger.info("Invalid value returned from get_linac_function_mode " + str(result))
            raise exception_from_err("Failed to get linac function mode", result)

    def get_message_date_time(self, msg_handle):
        '''
        Get the date and time fields of a Vx message.

        Args:
        msg_handle (int)- Handle of Vx message

        Returns:
        String of <date time>

        '''
        buff_sz = self.icom.iCOMGetDate(msg_handle, None)
        msg_date = create_string_buffer(buff_sz)
        self.icom.iCOMGetDate(msg_handle, msg_date)

        buff_sz = self.icom.iCOMGetTime(msg_handle, None)
        msg_time = create_string_buffer(buff_sz)
        self.icom.iCOMGetTime(msg_handle, msg_time)

        # In python 3, create_string_buffer() creates a c_char array where its raw data is in
        # bytes. Convert the msg_date and msg_time data from bytes to string using decode()
        return msg_date.raw.decode('utf-8') + " " + msg_time.raw.decode('utf-8')

    def get_message_seq_number(self, msg_handle):
        '''
        Get the sequence number fields of a Vx message.

        Returns:
        Integer value of message sequence number.

        Each iCom-Vx message contains a unique sequence number. This function call extracts the
        sequence number from the message.
        The sequence number can be used to determine whether messages have been missed. The range
        values in the sequence number should be 0 to 65535 (unsigned short), with the negative
        values representing error codes. Due to a known error, the return value for this function actually
        returns a sign extended short ranging from -32768 to 32767, hence the error codes are
        masked.

        '''
        result = self.icom.iCOMGetSeqNumber(msg_handle)

        if result > -32768:
            # Converting signed short to unsigned short between 0 and 65535
            self.last_seqnum = c_ushort(result).value
            return self.last_seqnum
        else:
            raise exception_from_err("Failed to get Vx seq number", result)

    message_list = []

    def update_message_list(self):
        '''
        Adds messages from VX queue to this instance.
        Retrieve messages from self.message_list
        '''
        logger.info("icon update_message_list")
        self.message_list = self.message_list[-50:]
        while True:
            try:
                # Messages are added to the queue by a watchdog,
                # which guarantees that a message will be received by the iCom DLL
                # at least every 5 seconds while a connection is open.
                # So set timeout to less than this to prevent infinite loop.
                msg = self.get_next_message(timeout=100)
                self.message_list.append(msg)
            except Exception:                # expect a TIMEOUT error as we reach the end of the queue, messages are generated

                break

        return True

    def get_next_message(self, timeout=10000):
        '''
        Get the next Vx message in the Vx server queue.

        Extract, clean and package into a VxMessage object.

        Returns:

        VxMessage containing message values.
        '''
        # logger.debug("icom - get_next_message")
        def extract_and_add(vxmsg, tag, part, value):

            tag_val = str(hex(tag.value)).lstrip('0x')[:8]
            tag_def = self.def_from_tag(tag_val)
            # For python 3, use decode() instead of str() to convert bytes to string
            value_clean = value.raw.decode('ascii').strip('\x00')
            data = (tag_val, part.raw.decode('ascii'), value_clean)
            self.add_to_message_dict(vxmsg, tag_def, data)

        vxmsg = {}

        if self.icom_handle > 0:
            result = self.icom.iCOMWaitForMessage(self.icom_handle, timeout)

            if result < 1:
                logger.error("iCOMWaitForMessage failed - " + str(result))
                # raise IcomError("iCOMWaitForMessage failed : " + decode(result))
                raise exception_from_err("iCOMWaitForMessage failed", result)

            icom_msg = result
            vxmsg['MESSAGE_HANDLE'] = str(icom_msg)
            seqnum = self.get_message_seq_number(icom_msg)
            vxmsg['MESSAGE_SEQNUM'] = str(seqnum)
            datetime = self.get_message_date_time(icom_msg)
            vxmsg['MESSAGE_DATETIME'] = datetime
            linac_mode = self.get_linac_function_mode(icom_msg)
            vxmsg['LINAC_FUNCTION_MODE'] = linac_mode
            state = self.get_machine_state(icom_msg)
            vxmsg['MACHINE_STATE'] = state

            tag = DWORD()
            part = create_string_buffer(1)
            value = create_string_buffer(255)
            result = self.icom.iCOMGetFirstTagValue(icom_msg, byref(tag), part, value)

            vxmsg['ICOM_HANDLE'] = str(result)

            if result == ICOM_RESULT_OK:
                extract_and_add(vxmsg, tag, part, value)

            while result == ICOM_RESULT_OK:
                tag = DWORD()
                part = create_string_buffer(1)

                try:
                    buff_sz = self.icom.iCOMGetNextTagValue(icom_msg, byref(tag), part, None)
                    value = create_string_buffer(255)
                    result = self.icom.iCOMGetNextTagValue(icom_msg, byref(tag), part, value)
                    if result == ICOM_RESULT_OK:
                        extract_and_add(vxmsg, tag, part, value)

                except WindowsError as we:
                    logger.exception("Failed to get next Vx message - " + str(we))
                    raise IcomError("Failed to get next Vx message", str(we))
            # logger.debug( "get vx message, MESSAGE_HANDLE - "+ vxmsg['MESSAGE_HANDLE']+", MESSAGE_SEQNUM - "+ vxmsg['MESSAGE_SEQNUM'] )

            try:
                result = self.icom.iCOMDeleteMessage(icom_msg)
                # logger.debug("delete message "+ str(icom_msg)+" result - " + str(result))
                if result != 1:
                    raise exception_from_err("iCOMDeleteMessage failed", result)
            except Exception:
                logger.error("failed to delete message result - " + str(icom_msg))

            return VxMessage(vxmsg)

    def disconnect(self):
        '''
        Close connection to Vx server.
        '''
        if hasattr(self, "icom_handle"):
            logger.info("iCOMDisconnect icom_handle " + str(self.icom_handle))
            return self.icom.iCOMDisconnect(self.icom_handle)

    def def_from_tag(self, tag):
        '''
        Get textual definition from numeric tag.

        Args:
        tag(str) -  Hex string of tag.
        '''
        try:
            return tag_to_def_map[tag.upper()]
        except Exception:
            return "Unknown *" + tag + "*"

    def add_to_message_dict(self, vxmsg, tag_def, data):

        if tag_def in vxmsg:
            vxmsg[tag_def].update({data[1]: data[2]})
        else:
            valdict = {}
            vxmsg[tag_def] = {'tag': data[0]}
            vxmsg[tag_def].update({data[1]: data[2]})

    def wait_until_state(self, state, timeout=30, filepath=""):

        #           Repeatedly read next Vx message from front of Vx server queue
        #           until one is reached that has a matching machine state
        #           If the queue has some earlier old data this will be read
        #           first and so may take some time to reach the message with
        #           a state change

        #           Args:
        #               state(str) - message state to wait for
        #               timeout(int) - number of seconds to wait
        #               filepath(str) - file to write the message to

        #           Returns:
        #               True if message found matching the state, False otherwise

        tick = 0
        while tick < timeout:
            # self.update_message_list()
            # msg=self.message_list[-1]
            msg = self.get_next_message()
            if filepath:
                msg.write_to_file(filepath)
            if msg.get_machine_state() == state:
                logger.info("wait_until_state success - " + state)
                return True
            tick += 1
            time.sleep(1)
        logger.info("wait_until_state timeout - " + state)
        return False

    def check_latest_msg_state(self, state, timeout=30, filepath=""):

        #           Read the most recent Vx message - i.e from back of Vx server queue
        #           and compare to state until it matches or there is a timeout

        #           Args:
        #               state(str) - message state to compare against
        #               timeout(int) - number of seconds to wait
        #               filepath(str) - file to write the message to

        #           Returns:
        #               True if message found matching the state, False otherwise

        tick = 0
        while tick < timeout:
            self.update_message_list()
            msg = self.message_list[-1]
            if filepath:
                msg.write_to_file(filepath)
            if msg.get_machine_state() == state:
                logger.info("check_latest_msg_state success - " + state)
                return True
            tick += 1
            time.sleep(1)
        logger.info("check_latest_msg_state timeout - " + state)
        return False

    def get_latest_message(self):
        # get latest Vx message

        self.update_message_list()
        return self.message_list[-1]

    # get vx msg handle
    def get_vx_msg_handle(self):
        if self.icom_handle > 0:
            m_handle = self.icom.iCOMWaitForMessage(self.icom_handle, 10000)
        return m_handle


class VxMessage():
    '''
    Representation of a Vx message.

    '''

    def __init__(self, message_dict):

        self._rawmsg = message_dict
        self.raw_msg = message_dict
        self.fill_out_tag_values()

    def pretty_print(self):
        '''
        Print out the backing dictionary in clear format.
        Useful for debugging.
        '''
        # import pprint
        pp = pprint.PrettyPrinter(indent=4)
        pp.pprint(self._rawmsg)

    def fill_out_tag_values(self, default=''):
        '''
        Fill out the missing values with default value.
        VX messages returned by iCOM will not have values for empty
        dimensions e.g P, R, S.
        This functions sets those values to the default value.
        '''
        for tagdef, vals in self._rawmsg.items():
            if isinstance(vals, dict):

                vals.setdefault('P', default)
                vals.setdefault('R', default)
                vals.setdefault('S', default)

    def fill_out_empty_tags(self):
        '''
        Pad out backing dictionary with a placeholder entry with empty values for P, R and S fields.
        '''
        for tagdef, taghex in defn_to_tag_map.items():
            if tagdef not in self._rawmsg:
                self._rawmsg[tagdef] = {'tag': taghex, 'P': '', 'R': '', 'S': ''}

    def write_to_file(self, vxfile, include_empty_tags=False):
        '''
        Write Vx message to CSV file.

        Current output closely matches the output of the VXClient.exe as close as possible for comparison.
        (Appends to file, does not overwrite.)

        Args:
        vxfile (str) - File path to output file.
        include_empty_tags(bool) - Include entry tags that are entirely without values
        '''
        if include_empty_tags:
            # Has side effect, backing dict is changed.
            self.fill_out_empty_tags()

        lines_dict = {}

        for tagdef, vals in self._rawmsg.items():
            if isinstance(vals, dict):
                # Flatten each tag dictionary to comma separated values
                # Tag label, hex tag string, Run, Set, Prescribed
                # ElectronAppFitment,5001000E,-32767,-32767,-32767
                line = tagdef + "," + vals['tag'].upper() + "," + vals['R'] + "," + vals['S'] + "," + vals['P'] + "\n"
                lines_dict[vals['tag']] = line

        lines = []
        lines.append("\n")
        lines.append("VX Seq number =" + self._rawmsg['MESSAGE_SEQNUM'] + "\n")
        lines.append("Linac Status =" + self._rawmsg['MACHINE_STATE'] + "\n")
        lines.append("Time =" + self._rawmsg['MESSAGE_DATETIME'] + "\n")

        # Dummy data line to align with Vx Client output.
        lines.append("Update Rate =0.83" + "\n")

        lines.append("Tag name,Hex Tag,Run,Set,Prescribed" + "\n")
        lines.append("\n")

        # Build lines list in the order found in Vx Client csv for ease of comparison.
        self.add_line_to_list(lines_dict, lines, 0x50010001, 0x500100BC)
        self.add_line_to_list(lines_dict, lines, 0x50020007, 0x50020014)
        self.add_line_to_list(lines_dict, lines, 0x70010001, 0x70010050)
        self.add_line_to_list(lines_dict, lines, 0x70020002, 0x7002000B)
        self.add_line_to_list(lines_dict, lines, 0x50010101, 0x50010150)
        self.add_line_to_list(lines_dict, lines, 0x50010201, 0x50010250)

        with open(vxfile, 'a+') as f:
            f.writelines(lines)

    def add_line_to_list(self, lines_dict, lines, start, end):
        '''
        Add dict values to lines list in range start to end to lines_dict.

        Args:
        lines_dict - Source dict with required values
        lines - List to add values to
        start - Start of tag hex range
        end - End of tag hex range
        '''
        for i in range(start, end + 1):
            hex_tag = hex(i)[2:]
            try:
                lines.append(lines_dict[hex_tag])
            except KeyError:
                pass

    def get_run_by_tagname(self, tagname):
        '''
        Get the Run value for a tag.

        Args:
        tagname (Str) -  e.g. BeamTimer

        Returns:
        RUN value as string.
        '''
        tagvals = self._rawmsg[tagname]
        run_val = tagvals['R']
        return run_val

    def get_set_by_tagname(self, tagname):
        '''
        Get the Set value for a tag.

        Args:
        tagname (Str) -  e.g. BeamTimer

        Returns:
        SET value as string.
        '''
        tagvals = self._rawmsg[tagname]
        set_val = tagvals['S']
        return set_val

    def get_prescribed_by_tagname(self, tagname):
        '''
        Get the Prescribed value for a tag.

        Args:
        tagname (Str) - Tag label e.g. BeamTimer

        Returns:
        PRESCRIBED value as string.
        '''
        tagvals = self._rawmsg[tagname]
        prescribed_val = tagvals['P']
        return prescribed_val

    def sequence_num(self):
        '''
        Get the message Sequence number as string.
        '''
        return self._rawmsg['MESSAGE_SEQNUM']

    def get_machine_state(self):
        '''
        Get the message machine state value as string.
        '''
        return self._rawmsg['MACHINE_STATE']

    def date_time(self):
        '''
        Get the message <date time> as string.
        '''
        return self._rawmsg['MESSAGE_DATETIME']

